"""LearnGED · Estudios sociales · Lección 8.1 · Escenarios de varias fuentes: texto, gráfica y mapa (EN/ES).
Fuente: sociales/soc-8-1.html (Escenario A: Luisiana 1896–1904; Escenario B: inmigración 1901–1910 y nacidos
en el extranjero en 1870, 1890 y 1910; la práctica «¿Contradicción real o diferencia de alcance?»).
Datos: registro de votantes negros en Luisiana, 130,344 (1896) y 1,342 (1904); Constitución de Luisiana de 1898
(impuesto electoral, prueba de alfabetización y cláusula del abuelo, 1 de enero de 1867); 8.8 millones de inmigrantes
en 1901–1910; nacidos en el extranjero: 14.4 % (1870), 14.8 % (1890), 14.7 % (1910), Oficina del Censo.
Uso: python3 tools/build_soc_8_1.py
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from sociales import C, t, documento, cita, escenario, fuente

N = "8-1"
F = 'font-family="Segoe UI, Arial, sans-serif"'


def titulo():
    return t("Multiple-source scenarios: text, graph, and map", "Escenarios de varias fuentes: texto, gráfica y mapa")


def grafica_luisiana():
    spec = {"tipo": "barras", "xEtq": t("Year", "Año"), "yEtq": t("Voters (thousands)", "Votantes (miles)"), "py": 20,
            "barras": [{"etq": "1896", "valor": 130.344, "txt": "130,344"}, {"etq": "1904", "valor": 1.342, "txt": "1,342"}]}
    aria = t("Bar graph of Black voters registered in Louisiana. In 1896 there were 130,344. In 1904 there were 1,342. The second bar is so small it can hardly be told apart from the axis.",
             "Gráfica de barras de los votantes negros registrados en Luisiana. En 1896 había 130,344. En 1904 quedaban 1,342. La segunda barra es tan pequeña que apenas se distingue del eje.")
    return C.grafica(spec, aria, ancho=520, alto=300)


def svg_reloj():
    """El reloj de un escenario de tres preguntas: 90 s, 90 s, 45 s, 45 s (ancho proporcional al tiempo)."""
    tramos = [(90, t("Read the sources", "Leer las fuentes"), "#7646ad"), (90, t("Question 1", "Pregunta 1"), "#5e3591"),
              (45, t("Q 2", "P 2"), "#2e6b30"), (45, t("Q 3", "P 3"), "#2e6b30")]
    aria = t("A time bar for one scenario with three questions, 4 minutes and 30 seconds in all. About 90 seconds to read the sources, 90 seconds for the first question, and about 45 seconds each for the second and third. The last two are short because you already know where everything is.",
             "Barra de tiempo de un escenario de tres preguntas, 4 minutos y 30 segundos en total. Unos 90 segundos para leer las fuentes, 90 segundos para la primera pregunta y unos 45 segundos para cada una de la segunda y la tercera. Las dos últimas son cortas porque ya sabe dónde está cada cosa.")
    s = [f'<svg class="diagrama" style="max-width:720px" viewBox="0 0 720 150" role="img" aria-label="{aria}" xmlns="http://www.w3.org/2000/svg">']
    x, esc = 20, 680 / 270
    for seg, etq, col in tramos:
        w = seg * esc
        s.append(f'<rect x="{x:.1f}" y="30" width="{w - 4:.1f}" height="56" rx="8" fill="{col}"/>'
                 f'<text x="{x + (w - 4) / 2:.1f}" y="55" text-anchor="middle" {F} font-size="15" font-weight="700" fill="#fff">{etq}</text>'
                 f'<text x="{x + (w - 4) / 2:.1f}" y="76" text-anchor="middle" {F} font-size="14" fill="#fff">≈ {seg} s</text>')
        x += w
    s.append(f'<text x="20" y="20" {F} font-size="14" fill="#3d4753">0:00</text><text x="700" y="20" text-anchor="end" {F} font-size="14" fill="#3d4753">4:30</text>')
    s.append(f'<text x="360" y="114" text-anchor="middle" {F} font-size="14" fill="#1a2330">{t("If question 2 takes as long as question 1, you are rereading.", "Si la pregunta 2 le cuesta lo mismo que la 1, está releyendo.")}</text>')
    s.append(f'<text x="360" y="136" text-anchor="middle" {F} font-size="14" fill="#1a2330">{t("More than 2 minutes on one question: mark it and move on.", "Más de 2 minutos en una pregunta: márquela y siga.")}</text>')
    s.append("</svg>")
    return "".join(s)


